pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address spender, uint256 amount) public {
        vm.assume(spender != address(0));
        vm.assume(amount > 0);
        // The deployer (this) has balance and can approve
        c.approve(spender, amount);
        // Now force a call to transferFrom, which uses allowance
        // If owner() returns zero address, the _spendAllowance check will revert
        // because the owner (this) will be interpreted as zero address, causing require(owner != address(0)) to fail in _approve
        bool reverted = false;
        try c.transferFrom(address(this), address(this), 0) {
            // success
        } catch {
            reverted = true;
        }
        assertTrue(!reverted, "transferFrom should not revert when owner is correct");
    }
}

