pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address owner, address newOwner, address spender, uint256 amount) public {
        vm.assume(newOwner != address(0));
        vm.assume(owner != address(0));
        vm.assume(spender != address(0));

        // Set owner to be the caller
        vm.prank(c.owner());
        c.setCaller(owner);

        // Call allowance from owner's perspective (any spender, amount)
        if (owner != address(0)) {
            vm.prank(owner);
        }
        c.allowance(owner, spender);

        // Now attempt transferOwnership as owner
        if (owner != address(0)) {
            vm.prank(owner);
        }
        (bool success, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));

        // The property: transferOwnership should succeed when called by owner with non-zero newOwner
        // In the reference, it succeeds (success == true); in the mutant, it might revert when newOwner != msg.sender
        // But msg.sender is owner, so the mutant reverts if newOwner != owner
        assertTrue(success || newOwner == owner);
    }
}

