pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address spender, address sender, uint256 approveAmount, uint256 transferAmount) public {
        // Ensure we can approve and transfer
        vm.assume(spender != address(0) && sender != address(0) && sender != address(c));
        vm.assume(approveAmount > 0 && transferAmount > 0 && transferAmount <= approveAmount);

        // Give sender tokens
        vm.deal(sender, 1 ether);

        // Approve spender to spend from sender
        vm.prank(sender);
        c.approve(spender, approveAmount);

        // Get initial allowance
        uint256 initialAllowance = c.allowance(sender, spender);

        // Now transfer from sender to pairAddress using spender
        vm.prank(spender);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transferFrom.selector, sender, address(c.pairAddress()), transferAmount));

        // Get final allowance
        uint256 finalAllowance = c.allowance(sender, spender);

        // Rule: The allowance should not have decreased if transfer succeeded (original behavior with fee)
        // In reference: transfer to pair takes 5% fee, so actual transferred amount is less
        // But allowance is only reduced by the transferred amount (which is less than transferAmount due to fee)
        // The allowance decrease should equal the amount actually transferred (not transferAmount)
        // Since fee is 5%, transferred amount = transferAmount * 95 / 100
        assertTrue(finalAllowance == initialAllowance - (transferAmount * 95 / 100) || finalAllowance == initialAllowance);
    }
}

