pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address addr1, address addr2, uint256 amount1, uint256 amount2) public {
        // Bound amounts to be realistic
        vm.assume(addr1 != address(0) && addr2 != address(0) && addr1 != addr2);
        amount1 = bound(amount1, 0, 1e30);
        amount2 = bound(amount2, 0, 1e30);

        // Get initial total supply
        uint256 initialSupply = c.totalSupply();

        // Get initial balances
        uint256 initialBal1 = c.balanceOf(addr1);
        uint256 initialBal2 = c.balanceOf(addr2);

        // Compute expected total supply: sum of all balances (we only track these two plus the owner)
        // But the contract has more holders (deployer, liquidity pool, etc.), so we need a different approach.
        // Instead, we can test that totalSupply() never decreases after minting, or use a simpler property.
        // Let's test that after transfers, the sum of balances of two specific addresses is bounded by total supply.

        // Transfer amount1 from owner to addr1
        vm.prank(address(this));
        c.transfer(addr1, amount1);

        // Transfer amount2 from addr1 to addr2
        vm.prank(addr1);
        c.transfer(addr2, amount2);

        // Now check that the sum of balances of addr1 and addr2 is at most totalSupply
        uint256 totalSupply = c.totalSupply();
        uint256 balance1 = c.balanceOf(addr1);
        uint256 balance2 = c.balanceOf(addr2);

        // General rule: the sum of any subset of balances cannot exceed totalSupply
        assertTrue(balance1 + balance2 <= totalSupply, "Sum of balances exceeds total supply");
    }
}

