pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address owner, address spender, uint256 amount) public {
        vm.assume(owner != address(0));
        vm.assume(spender != address(0));
        // Ensure owner has enough tokens to attempt transfer
        uint256 totalSupply = c.totalSupply();
        vm.assume(totalSupply > 0);
        vm.assume(amount <= totalSupply);

        // Get the owner's balance before any transfer
        uint256 balanceBefore = c.balanceOf(owner);

        // Approve unlimited allowance
        vm.prank(owner);
        c.approve(spender, type(uint256).max);

        // Perform transferFrom from owner to some other address
        address receiver = address(0xdead);
        uint256 transferAmount = amount;
        // Ensure we don't try to transfer more than balance before
        if (transferAmount > balanceBefore) {
            transferAmount = balanceBefore;
        }

        // Execute transferFrom
        vm.prank(spender);
        bool success = c.transferFrom(owner, receiver, transferAmount);

        // Get the post-transfer balance
        uint256 balanceAfter = c.balanceOf(owner);

        // General rule: The decrease in owner's balance must be exactly the transferred amount (if successful)
        // In reference: balanceAfter == balanceBefore - transferAmount
        // In mutant (balanceOf returns 0): balanceAfter == 0, but balanceBefore could be > 0, causing violation
        // We express: The actual transferred amount (if successful) does not exceed balanceBefore
        // For the mutant, balanceOf(owner) returns 0 before, so transferFrom reverts, or if it succeeds due to allowance, the rule still holds
        // Better: The sum of balances of all accounts equals totalSupply, but mutant breaks that.
        // Simpler: For the owner, balanceOf returns a non-negative value.
        // Actually, the required general rule: balanceOf(owner) returns the same value as the amount that can be transferred from owner with unlimited allowance and no other transfers.
        // We use: If transferFrom succeeded, then balanceAfter == balanceBefore - transferAmount
        // The mutant will break because balanceAfter = 0 but balanceBefore - transferAmount > 0.

        assertTrue(!success || balanceAfter == balanceBefore - transferAmount, "balance invariant violated");
    }
}

