import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address owner, address spender) public {
        // Edge case: zero address owner is allowed in ERC20.approve but the reference allowance is 0 (not max)
        vm.assume(owner != address(0) && spender != address(0));
        // Call allowance
        uint256 allowance = c.allowance(owner, spender);
        // General rule: the reference never returns type(uint256).max for any allowance
        assertTrue(allowance < type(uint256).max, "allowance should be less than max uint256");
    }
}

