pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address owner, address spender) public {
        uint256 ownerBalance = c.balanceOf(owner);
        uint256 allowanceValue = c.allowance(owner, spender);
        assertTrue(allowanceValue <= ownerBalance);
    }
}
